inline constexpr std::size_t count = sizeof(table) / sizeof(table[0]);

inline bool masked_equal(const std::uint8_t* at, const char* sig) noexcept {
    while (*sig) {
        if (*sig == ' ') { ++sig; continue; }
        if (sig[0] == '?' && sig[1] == '?') { sig += 2; ++at; continue; }
        if (sig[0] == '?') { ++sig; ++at; continue; }
        auto hex = [](char c) -> int { return c <= '9' ? c - '0' : (c | 0x20) - 'a' + 10; };
        int want = (hex(sig[0]) << 4) | hex(sig[1]);
        if (*at != static_cast<std::uint8_t>(want)) return false;
        sig += 2; ++at;
    }
    return true;
}

/* Scan [base, base+size). Code only: the caller passes the executable range. */
inline result find(const std::uint8_t* base, std::size_t size, const anchor& a) noexcept {
    if (!a.signature[0]) return { nullptr, status::unsigned_anchor };
    const std::uint8_t* first_hit = nullptr;
    std::size_t sig_len = 0;
    for (const char* s = a.signature; *s; ++s)  /* one per token: bytes, not characters */
        if (*s != ' ' && (s == a.signature || s[-1] == ' ')) ++sig_len;
    for (std::size_t i = 0; i + sig_len <= size; ++i) {
        if (!masked_equal(base + i, a.signature)) continue;
        if (first_hit) return { nullptr, status::ambiguous };
        first_hit = base + i;
    }
    return { first_hit, first_hit ? status::ok : status::not_found };
}

/* Apply the anchor recipe. `slot` = match + insn_len, then + int32 disp. */
inline const std::uint8_t* deref(const std::uint8_t* match, const anchor& a) noexcept {
    if (a.target_kind == kind::function) return match + a.offset;
    std::int32_t disp;
    std::memcpy(&disp, match + a.disp_at, sizeof disp);
    return match + a.insn_len + disp;
}

inline const anchor* by_name(const char* name) noexcept {
    for (const auto& a : table) {
        const char* n = a.name; const char* m = name;
        while (*n && *n == *m) { ++n; ++m; }
        if (!*n && !*m) return &a;
    }
    return nullptr;
}

/* ---- xref-chain anchors (additive; `table`/`anchor`/`find`/`deref` above are unchanged) ----------
 * An anchor without a unique signature of its own keeps its `table` row (empty signature) and gets a
 * `chains` row: a unique start (`from_signature`, or the signed `table` anchor `from_anchor`) and
 * `step_count` steps from `chain_steps[first_step]`. The cursor is an absolute address:
 *   call_target {at}            cursor = target of the E8 rel32 at cursor+at (must land in code)
 *   rip_target  {at, a, b}      cursor = cursor+at + b (insn_len) + int32 [cursor+at+a (disp_at)]
 *   add         {a}             cursor += a
 *   deref       {}              cursor = u64 [cursor] (the value is not range-checked; later reads are)
 *   nth_call    {a, b}          cursor = target of the a-th (0-based) E8 byte in [cursor, cursor+b)
 *                               whose rel32 lands in code (byte-level; the generator proved the order)
 *   expect      {at, signature} masked compare at cursor+at; does not move the cursor
 * Every read is bounds-checked against code or [module, module+module_size). No step reads a
 * gs:[0x58] load, so chains also resolve under HLE hosts that rewrite those loads. */
enum class step_op : std::uint8_t { call_target = 0, rip_target = 1, add = 2, deref = 3, nth_call = 4, expect = 5 };

struct chain_step {
    step_op      op;
    std::int32_t at;
    std::int32_t a;
    std::int32_t b;
    const char*  signature; /* expect only; "" otherwise */
};

struct chain {
    const char*   name;
    const char*   from_anchor;    /* "" when from_signature is used */
    const char*   from_signature; /* "" when from_anchor is used */
    std::uint16_t first_step;
    std::uint16_t step_count;
};

/* state: ok; not_found (start missing or a step failed); ambiguous (start matched twice);
 * unsigned_anchor (from_anchor unknown or itself unsigned). failed_step: -1 = start, else step index. */
struct chain_result { const std::uint8_t* address; status state; std::int32_t failed_step; };

