inline constexpr std::size_t chain_count = 18;

inline std::size_t sig_length(const char* sig) noexcept {
    std::size_t n = 0;
    while (*sig) {
        if (*sig == ' ') { ++sig; continue; }
        if (sig[0] == '?') { sig += (sig[1] == '?') ? 2 : 1; ++n; continue; }
        sig += 2; ++n;
    }
    return n;
}

inline bool span_in(std::uintptr_t p, std::size_t n, const std::uint8_t* lo, std::size_t size) noexcept {
    const std::uintptr_t b = reinterpret_cast<std::uintptr_t>(lo);
    return p >= b && p - b <= size && n <= size - (p - b);
}

inline const chain* chain_by_name(const char* name) noexcept {
    for (const auto& c : chains) {
        const char* n = c.name; const char* m = name;
        while (*n && *n == *m) { ++n; ++m; }
        if (!*n && !*m) return &c;
    }
    return nullptr;
}

/* module/module_size: the whole mapped image (bounds for data reads).
 * code/code_size: the executable range, as passed to find(). */
inline chain_result resolve_chain(const std::uint8_t* module, std::size_t module_size,
                                  const std::uint8_t* code, std::size_t code_size, const chain& c) noexcept {
    result start{ nullptr, status::not_found };
    if (c.from_anchor[0]) {
        const anchor* src = by_name(c.from_anchor);
        if (!src || !src->signature[0]) return { nullptr, status::unsigned_anchor, -1 };
        start = find(code, code_size, *src);
        if (start.state == status::ok) start.address = deref(start.address, *src);
    } else {
        const anchor tmp{ c.name, c.from_signature, kind::function, 0, -1, 0, "", "" };
        start = find(code, code_size, tmp);
    }
    if (start.state != status::ok) return { nullptr, start.state, -1 };
    std::uintptr_t cur = reinterpret_cast<std::uintptr_t>(start.address);
    const std::uintptr_t code_lo = reinterpret_cast<std::uintptr_t>(code);
    auto in_code = [&](std::uintptr_t t) noexcept { return t >= code_lo && t - code_lo < code_size; };
    for (std::uint16_t i = 0; i < c.step_count; ++i) {
        const chain_step& s = chain_steps[c.first_step + i];
        const chain_result fail{ nullptr, status::not_found, static_cast<std::int32_t>(i) };
        const std::uintptr_t p = cur + static_cast<std::uintptr_t>(static_cast<std::intptr_t>(s.at));
        switch (s.op) {
        case step_op::call_target: {
            if (!span_in(p, 5, code, code_size)) return fail;
            const std::uint8_t* q = reinterpret_cast<const std::uint8_t*>(p);
            if (q[0] != 0xE8) return fail;
            std::int32_t rel; std::memcpy(&rel, q + 1, sizeof rel);
            cur = p + 5 + static_cast<std::uintptr_t>(static_cast<std::intptr_t>(rel));
            if (!in_code(cur)) return fail;
            break;
        }
        case step_op::rip_target: {
            const std::uintptr_t d = p + static_cast<std::uintptr_t>(static_cast<std::intptr_t>(s.a));
            if (!span_in(d, 4, code, code_size)) return fail;
            std::int32_t disp; std::memcpy(&disp, reinterpret_cast<const void*>(d), sizeof disp);
            cur = p + static_cast<std::uintptr_t>(static_cast<std::intptr_t>(s.b))
                    + static_cast<std::uintptr_t>(static_cast<std::intptr_t>(disp));
            if (!span_in(cur, 1, module, module_size)) return fail;
            break;
        }
        case step_op::add:
            cur += static_cast<std::uintptr_t>(static_cast<std::intptr_t>(s.a));
            break;
        case step_op::deref: {
            if (!span_in(cur, sizeof(std::uint64_t), module, module_size)) return fail;
            std::uint64_t v; std::memcpy(&v, reinterpret_cast<const void*>(cur), sizeof v);
            cur = static_cast<std::uintptr_t>(v);
            break;
        }
        case step_op::nth_call: {
            if (s.a < 0 || s.b < 5) return fail;
            std::int32_t seen = -1;
            bool found = false;
            for (std::int32_t k = 0; k + 5 <= s.b; ++k) {
                const std::uintptr_t q = cur + static_cast<std::uintptr_t>(k);
                if (!span_in(q, 5, code, code_size)) break;
                const std::uint8_t* b = reinterpret_cast<const std::uint8_t*>(q);
                if (b[0] != 0xE8) continue;
                std::int32_t rel; std::memcpy(&rel, b + 1, sizeof rel);
                const std::uintptr_t t = q + 5 + static_cast<std::uintptr_t>(static_cast<std::intptr_t>(rel));
                if (!in_code(t)) continue;
                if (++seen == s.a) { cur = t; found = true; break; }
            }
            if (!found) return fail;
            break;
        }
        case step_op::expect: {
            const std::size_t n = sig_length(s.signature);
            if (!n || !span_in(p, n, module, module_size)) return fail;
            if (!masked_equal(reinterpret_cast<const std::uint8_t*>(p), s.signature)) return fail;
            break;
        }
        default:
            return fail;
        }
    }
    return { reinterpret_cast<const std::uint8_t*>(cur), status::ok, -1 };
}

/* One entry point for any anchor: its signature (find + deref) or, if unsigned, its chain. */
inline result resolve_anchor(const std::uint8_t* module, std::size_t module_size,
                             const std::uint8_t* code, std::size_t code_size, const anchor& a) noexcept {
    if (a.signature[0]) {
        result r = find(code, code_size, a);
        if (r.state == status::ok) r.address = deref(r.address, a);
        return r;
    }
    const chain* c = chain_by_name(a.name);
    if (!c) return { nullptr, status::unsigned_anchor };
    const chain_result r = resolve_chain(module, module_size, code, code_size, *c);
    return { r.address, r.state };
}

